function Tin({ oil, kick }) {
  const reduce = useReducedMotion();
  const ang = useMotionValue(-205);
  const vel = useRef(0);
  const drag = useRef(null);
  useEffect(() => { vel.current += 0.55; }, [kick]);
  useAnimationFrame((t, d) => {
    if (drag.current) return;
    const base = reduce ? 0 : 0.012;
    ang.set(ang.get() + (base + vel.current) * Math.min(d, 40));
    vel.current *= 0.94;
  });
  const down = (e) => { e.currentTarget.setPointerCapture(e.pointerId); drag.current = { x: e.clientX, t: performance.now(), v: 0 }; };
  const move = (e) => {
    const g = drag.current; if (!g) return;
    const now = performance.now(), dx = e.clientX - g.x;
    ang.set(ang.get() + dx * 0.45);
    g.v = (dx * 0.45) / Math.max(1, now - g.t); g.x = e.clientX; g.t = now;
  };
  const up = () => { if (drag.current) { vel.current = Math.max(-1.2, Math.min(1.2, drag.current.v)); drag.current = null; } };
  return (
    <div onPointerDown={down} onPointerMove={move} onPointerUp={up} onPointerCancel={up} className="relative cursor-grab touch-none select-none active:cursor-grabbing" style={{ width: R * 2 + 80, height: H + 150 }} role="img" aria-label={"A 500 ml tin of Gat " + oil.name + " olive oil. Drag to turn it."}>
      <div className="absolute bottom-[34px] left-1/2 h-[40px] w-[300px] -translate-x-1/2 rounded-[50%]" style={{ background: "radial-gradient(closest-side, rgba(29,31,18,0.38), rgba(29,31,18,0))" }} />
      <div className="absolute left-1/2 top-[70px] -translate-x-1/2" style={{ width: R * 2, height: H, perspective: 1300 }}>
        <div className="absolute inset-0" style={{ transformStyle: "preserve-3d", transform: "rotateX(-13deg)" }}>
          <motion.div className="absolute inset-0" style={{ transformStyle: "preserve-3d", rotateY: ang }}>
            {Array.from({ length: N }).map((_, i) => (
              <div key={i} className="absolute top-0 overflow-hidden" style={{ left: R - W / 2 - 0.5, width: W + 1, height: H, transform: "rotateY(" + (i * 360) / N + "deg) translateZ(" + (R - 0.5) + "px)", backfaceVisibility: "hidden" }}>
                <div className="absolute top-0 h-full" style={{ left: -i * W, width: L }}><Label oil={oil} /></div>
              </div>
            ))}
            <div className="absolute left-0 rounded-full" style={{ top: -R, width: R * 2, height: R * 2, transform: "rotateX(90deg)", background: "radial-gradient(circle, #DCD6CA 0 52%, #BDB6A8 53% 60%, #E7E2D7 61% 86%, #A69F90 87% 100%)" }}>
              <div className="absolute left-1/2 top-[30%] h-[44px] w-[70px] -translate-x-1/2 rounded-full border-[6px] border-[#A69F90]" />
            </div>
          </motion.div>
        </div>
        <div className="pointer-events-none absolute inset-0" style={{ borderRadius: "0 0 50% 50% / 0 0 14px 14px", background: "linear-gradient(90deg, rgba(20,16,8,0.42) 0%, rgba(20,16,8,0.08) 18%, rgba(255,255,255,0.32) 30%, rgba(255,255,255,0) 42%, rgba(20,16,8,0) 64%, rgba(20,16,8,0.5) 100%)" }} />
      </div>
    </div>
  );
}

