function Taste({ sel, setSel }) {
  const oil = OILS[sel];
  const names = ["Fruity", "Bitter", "Peppery"];
  return (
    <section className="grid grid-cols-[1fr_1fr] gap-16 px-14 py-24" style={{ background: oil.tin, color: oil.ink, transition: "background-color 400ms ease, color 400ms ease" }}>
      <div>
        <div className="flex gap-2" role="tablist" aria-label="Oil">
          {OILS.map((o, i) => <button key={o.name} role="tab" aria-selected={sel === i} onClick={() => setSel(i)} className="rounded-full border-2 px-4 py-1.5 text-[14px] font-semibold transition-colors duration-150" style={{ ...F, borderColor: "currentColor", background: sel === i ? oil.ink : "transparent", color: sel === i ? oil.tin : oil.ink }}>{o.name}</button>)}
        </div>
        <AnimatePresence mode="wait" initial={false}>
          <motion.div key={oil.name} initial={{ opacity: 0, y: 16 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10, transition: { duration: 0.15 } }} transition={{ duration: 0.35, ease: [0.23, 1, 0.32, 1] }}>
            <h2 className="mt-10 text-[7.5rem] uppercase leading-[0.82]" style={COND}>{oil.name}</h2>
            <p className="mt-6 max-w-[420px] text-[20px] leading-relaxed" style={F}>{oil.note}</p>
            <p className="mt-3 text-[15px] opacity-80" style={F}>{oil.pair}</p>
          </motion.div>
        </AnimatePresence>
      </div>
      <div className="flex flex-col justify-end gap-8">
        {names.map((n, i) => (
          <div key={n}>
            <div className="flex items-baseline justify-between text-[15px] font-semibold" style={F}><span>{n}</span><span style={{ fontVariantNumeric: "tabular-nums" }}>{Math.round(oil.taste[i] * 10)}/10</span></div>
            <div className="relative mt-3 h-6 overflow-hidden rounded-full border-2" style={{ borderColor: "currentColor" }}>
              <motion.div className="absolute inset-y-0 left-0 w-full origin-left rounded-full" style={{ background: "currentColor" }} animate={{ scaleX: oil.taste[i] }} transition={{ type: "spring", stiffness: 140, damping: 20 }} />
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}

