          return <g key={r + "-" + c}><path d={"M" + x + " " + (y + 26) + " v18"} stroke={OLV} strokeWidth="5" strokeLinecap="round" /><circle cx={x} cy={y} r="27" fill="#4F5E22" />{[0, 1, 2].map((k) => <circle key={k} cx={x - 12 + k * 11} cy={y - 6 + (k % 2) * 12} r="3.5" fill={OLV} />)}</g>;
        }))}
        <rect x="370" y="300" width="130" height="80" rx="6" fill={OX} /><path d="M360 304 L435 262 L510 304" fill="none" stroke={OX} strokeWidth="8" strokeLinejoin="round" /><text x="435" y="350" textAnchor="middle" fontSize="20" fill={YEL} style={COND}>THE PRESS</text>
